    const marketAnchor = Math.max(basePrice * 0.6, competitorMin * 0.95);
    const adjusted = basePrice * scarcityFactor * demandSurge * this.multiplier;
    return Math.max(marketAnchor, Math.min(basePrice * 3.5, adjusted));
